import moment from 'moment'
import { useCallback, useRef, useState } from 'react'
import { CustomText, Select } from '../../../../../components'
import DobInput from '../../../../../components/DobInput'
import TitleError from '../../../../../components/TitleError'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { POLICY_TIME_PERIOD } from '../../constants'
import { PolicyPeriodStyle } from './index.style'

function PolicyPeriod ({
  defaultStartDate, defaultEndDate, defaultPeriod, onPolicyPeriodSelect,
  errorField, errorTimePeriod, ...props
}) {
  const [policyDate, setPolicyDate] = useState({
    startDate: defaultStartDate || '',
    endDate: defaultEndDate || '',
    selectedTimePeriod: (defaultPeriod || 1)
  })

  const defaultTimePeriod = (defaultPeriod && `${defaultPeriod} tahun`) || '1 tahun'
  const dateRef = useRef()

  const handleDobSelect = useCallback((date) => {
    setPolicyDate((policyDate) => {
      const endDate = (date && moment(date, 'DD/MM/YYYY', true)) || {}
      const dateMap = {
        ...policyDate,
        startDate: date,
        endDate: endDate._isValid && (moment(date, 'DD/MM/YYYY').add(policyDate.selectedTimePeriod, 'year').format('DD/MM/YYYY'))
      }
      onPolicyPeriodSelect({
        ...dateMap
      })
      return {
        ...dateMap
      }
    })
  }, [onPolicyPeriodSelect])

  const handleSelectChange = useCallback((value) => {
    setPolicyDate((policyDate) => {
      const mappedData = {
        ...policyDate,
        endDate: moment(policyDate.startDate, 'DD/MM/YYYY').add(value, 'year').format('DD/MM/YYYY'),
        selectedTimePeriod: value
      }
      onPolicyPeriodSelect(mappedData)
      return {
        ...mappedData
      }
    })
  }, [onPolicyPeriodSelect])

  return (
    <PolicyPeriodStyle justify='space-between'>
      <div className='policy-date-left'>
        <TitleError
          title={LANG_STRINGS.policyStartDate}
          error={errorField ? LANG_STRINGS.required : ''}
          required
        />
        <DobInput
          errorField={errorField ? 'selectStartDate' : ''}
          name='selectStartDate'
          showCalenderIcon
          onDobSelect={handleDobSelect}
          minDate={new Date()}
          maxDate={moment(Date.now()).add(30, 'day')._d}
          ref={dateRef}
          defaultValue={defaultStartDate}
          className='policy-start-date'
          placeholder={LANG_STRINGS.enterPolicyStartDate}
        />
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='11px'
        >
          {
            policyDate.endDate ? `${LANG_STRINGS.policyEndDate}: ${policyDate.endDate}` : LANG_STRINGS.writeTheDateAndSelectTheTimePeriod
          }
        </CustomText>
      </div>
      <div className='policy-time-period-right'>
        <TitleError
          title={LANG_STRINGS.timePeriod}
          error={errorTimePeriod ? LANG_STRINGS.required : ''}
          required
        />
        <Select
          options={POLICY_TIME_PERIOD}
          name='timePeriod'
          value={policyDate.selectedTimePeriod}
          defaultValue={defaultTimePeriod}
          displayKey='title'
          dataKey='value'
          placeholder={LANG_STRINGS.timePeriod}
          className='policy-timer-period-select'
          errorField={errorTimePeriod ? 'timePeriod' : ''}
          border
          onChange={handleSelectChange}
        />
      </div>
    </PolicyPeriodStyle>
  )
}

export default PolicyPeriod
