import { Container, CustomText } from '../../../../../../components'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'
import { ManualPolicyStyle, ManualPolicyContainerStyle } from './index.style'
import StepsHeader from '../../../../../../components/StepsHeader'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { SEND_GOLD_ICON } from '../../../../../../images'
import BottomSheetSelect from '../../../../../../components/BottomSheetSelect'
import {
  MANUAL_FORM_STEP_1, FLEET_FORM_STEP_1, POLICY_TYPE,
  NEW_POLICY_USED_CAR, RENEW_POLICY_WITH_DIFFERENT_PROVIDER,
  RENEW_POLICY_WITH_SAME_PROVIDER
} from '../../../constants'
import { MANUAL_ORDER } from '../../../../../../constants/pkgCode'
import PolicyDataSection from '../../../components/PolicyDataSection'
import PolicyOfflineAddons from '../../../components/PolicyOfflineAddons'
import PolicyTransportation from '../../../components/PolicyTransportation'
import PolicyModification from '../../../components/PolicyModification'
import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { clearLocalStorage, getFromLocalStorageData, setToLocalStorage } from '../../../../../../helpers/localstorage'
import { OFFLINE_FORM_DATA } from '../../../../../../constants/cookies'
import { usePolicyContextValue } from '../../../context'
import { setPolicyState } from '../../../state/actions'
import { mapOfflineCasesDataForStepOne, getOfflineStepOneReBody } from '../../../../../../helpers/getPackageBody'
import BottomBtn from '../../../../../../components/BottomBtn'
import { useUpdateOfflineQuote } from '../../../state/hooks/usePolicyState'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { typeValid } from '../../../../../../helpers/validations'

function ManualPolicyContainer ({ match, history, location, ...props }) {
  const urlParams = useMemo(() => match?.params || {}, [match])
  const isEditPage = useMemo(() => (urlParams.quoteId && location.pathname.includes('edit')), [urlParams, location])
  const offlineLocalData = useRef(
    (isEditPage && (urlParams.quoteId !== 'normal'))
      ? mapOfflineCasesDataForStepOne(getFromLocalStorageData(OFFLINE_FORM_DATA))
      : getFromLocalStorageData(OFFLINE_FORM_DATA)
  )
  const otherPolicyType = useMemo(() => urlParams.purchaseType === MANUAL_ORDER ? LANG_STRINGS.fleet : LANG_STRINGS.manual, [urlParams.purchaseType])
  const isFleetPolicy = useMemo(() => otherPolicyType !== LANG_STRINGS.fleet, [otherPolicyType])
  const [isShowForm, setIsShowForm] = useState((!!offlineLocalData.current.protection_type || isEditPage))
  const [policyForm, setPolicyForm] = useState(offlineLocalData.current)
  const btnText = useMemo(() => {
    if (isEditPage) {
      return LANG_STRINGS.saveChanges
    }
    if (isShowForm) {
      return (isFleetPolicy ? LANG_STRINGS.chooseInsurance : LANG_STRINGS.insuredObject)
    }
    return LANG_STRINGS.next
  }, [isFleetPolicy, isEditPage, isShowForm])

  const [{
    GET_VEHICLE_YEAR_LOADER, GET_BRAND_LIST_LOADER, GET_VARIANT_LIST_LOADER,
    GET_REGION_CODE_LOADER, SEND_DOCUMENT_EMAIL_LOADER, UPDATE_OFFLINE_QUOTE_LOADER
  }, dispatchLoader] = useLoaderContextValue()
  const [, updateOfflineQuoteReq] = useUpdateOfflineQuote()
  const [
    {
      packageType, transportationType, vehicleUse, manualFleetFormErrors,
      addons = { ...(offlineLocalData.current.addons || {}) },
      customAddons = {
        custom_add_on: offlineLocalData.current.custom_add_on
      }
    },
    dispatchPolicyState
  ] = usePolicyContextValue()
  const [{ updateOfflineQuoteStatus, sendDocumentEmailStatus }, dispatchError] = useErrorContextValue()
  const that = useRef({
    packageType,
    transportationType,
    vehicleUse,
    ...offlineLocalData.current
  })
  const accessory = useRef({
    accessories: offlineLocalData.current.accessories || [],
    isModificationChecked: !!offlineLocalData.current.accessories?.length,
    totalSumInsured: offlineLocalData.current.totalSumInsured
  })

  const lossRatio = useMemo(() => {
    const protectionCode = policyForm?.protection_type?.code
    const isEnable = [
      NEW_POLICY_USED_CAR, RENEW_POLICY_WITH_DIFFERENT_PROVIDER,
      RENEW_POLICY_WITH_SAME_PROVIDER
    ].includes(protectionCode)
    if (isFleetPolicy && isEnable) {
      const required = NEW_POLICY_USED_CAR !== protectionCode
      return {
        required,
        title: `${LANG_STRINGS.lossRatio} ${required ? '' : `(${LANG_STRINGS.optional})`}`
      }
    }
    return null
  }, [policyForm.protection_type, isFleetPolicy])
  const [currencyType, setCurrencyType] = useState({
    currency_label: 'IDR',
    exchange_rate: '1',
    currency_symbol: 'Rp'
  })

  useEffect(() => {
    function resetErrorKey (key) {
      dispatchError(resetError({
        [key]: undefined
      }))
    }
    if (updateOfflineQuoteStatus === 'success') {
      history.goBack()
      clearLocalStorage()
      resetErrorKey('updateOfflineQuoteStatus')
    } else if (updateOfflineQuoteStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateOfflineQuoteStatus
      })
      resetErrorKey('updateOfflineQuoteStatus')
    }

    if (sendDocumentEmailStatus === 'success') {
      ShowSnackbar.success({
        visible: true,
        text: LANG_STRINGS.sendEmailSuccessful
      })
      resetErrorKey('sendDocumentEmailStatus')
    } else if (sendDocumentEmailStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateOfflineQuoteStatus
      })
    }
  }, [
    updateOfflineQuoteStatus, history, sendDocumentEmailStatus,
    dispatchError
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PROVIDER_LIST_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (offlineLocalData) {
      setCurrencyType({
        currency_label: offlineLocalData.current?.currency_label || 'IDR',
        exchange_rate: offlineLocalData.current?.exchange_rate || '1',
        currency_symbol: offlineLocalData.current?.currency_symbol || 'Rp'
      })
    }
  }, [offlineLocalData])

  const resetErrorsKey = useCallback((key) => {
    if (manualFleetFormErrors[key]) {
      delete manualFleetFormErrors[key]
      dispatchPolicyState(setPolicyState({
        manualFleetFormErrors: {
          ...manualFleetFormErrors
        }
      }))
    }
  }, [dispatchPolicyState, manualFleetFormErrors])

  const handleSelectPolicyType = useCallback((data) => {
    // set the protection data
    setPolicyForm(oldData => {
      const offlineForm = {
        ...oldData,
        protection_type: data
      }
      offlineLocalData.current = {
        ...offlineForm
      }
      setToLocalStorage(OFFLINE_FORM_DATA, offlineForm)
      return offlineForm
    })
  }, [])

  const handlePolicySectionData = useCallback((type, data) => {
    that.current = {
      ...that.current,
      [type]: data
    }
  }, [])

  const handleAccessories = useCallback((data) => {
    accessory.current = data
  }, [])

  const validateFormFields = useCallback(() => {
    let isValid = true
    const error = {}
    const validFormFields = isFleetPolicy ? FLEET_FORM_STEP_1 : MANUAL_FORM_STEP_1
    for (let index = 0; index < validFormFields.length; index++) {
      // here we are going to validate the fields
      const field = validFormFields[index]
      const item = that.current[field]
      if (field === 'policyPeriod') {
        if (!item?.startDate || !item?.selectedTimePeriod) {
          isValid = false
          error.startDate = !item?.startDate
          error.selectedTimePeriod = !item?.selectedTimePeriod
        }
      } else if (field === 'vehicle_plate_no' && !typeValid(field, item)) {
        isValid = false
        error[field] = item ? ERROR_LANG.incorrectFormat : LANG_STRINGS.required
      } else if (that.current.isCoinsurance && field === 'providerData') {
        if (that.current.isCoinsurance && !item) {
          isValid = false
          ShowSnackbar.error({
            visible: true,
            text: LANG_STRINGS.noProviderError
          })
        } else {
          let totalShare = 0
          let isProviderEmpty = true
          let leaderShare
          let isLeaderShareValid = true
          item.forEach((data) => {
            if (data.code && data.code !== '') {
              isProviderEmpty = false
              totalShare += data?.share_percent
              if (data.role === 'LEADER') {
                leaderShare = data.share_percent
              } else if (data.role === 'MEMBER' && leaderShare < data.share_percent) {
                isLeaderShareValid = false
              }
            }
          })
          if (totalShare > 100 || isProviderEmpty || !isLeaderShareValid) {
            isValid = false
            ShowSnackbar.error({
              visible: true,
              text: isProviderEmpty ? LANG_STRINGS.noProviderError : !isLeaderShareValid ? LANG_STRINGS.leaderShareErrorText : LANG_STRINGS.coinsuranceInfoText
            })
          }
        }
      } else if (!item) {
        isValid = false
        error[field] = true
      }
    }
    const accessoryError = {}
    if (accessory.current.isModificationChecked) {
      const { accessories = [] } = accessory.current
      if (!accessories.length) {
        isValid = false
        accessoryError.accessory0 = {
          name: true,
          sum_insured: true
        }
      }
      for (let index = 0; index < accessories.length; index++) {
        const accessory = accessories[index]
        // need to check is number isNaN to validate the value
        const sumIsValid = Number(accessory.sum_insured)
        if ((accessory.sum_insured === '') || isNaN(sumIsValid) || !accessory.name) {
          isValid = false
          accessoryError[`accessory${index}`] = {
            name: !accessory.name,
            sum_insured: ((accessory.sum_insured === '') || isNaN(sumIsValid))
          }
        }
      }
    }

    if (lossRatio?.required && !that.current.loss_ratio) {
      isValid = false
      error.loss_ratio = true
    }
    dispatchPolicyState(setPolicyState({
      manualFleetFormErrors: {
        accessoryError,
        ...error
      }
    }))
    return isValid
  }, [dispatchPolicyState, isFleetPolicy, lossRatio])

  const handleToChooseInsurance = useCallback(() => {
    // handle the choose insurance
    if (!isShowForm) {
      setIsShowForm(true)
      return
    }
    // here we are going to validate data
    if (!validateFormFields()) {
      // here we are saving to localstorage data
      return
    }
    let modelData = {}
    if (that.current.model && that.current.model_data) {
      modelData = {
        ...that.current.model_data
      }
    }
    // store all data to localstorage so that we can maintain the reload
    // or back button functionality
    const storageData = {
      ...offlineLocalData.current,
      ...that.current,
      ...(accessory.current.isModificationChecked ? {
        ...accessory.current,
        additional_sum_insured: accessory.current.totalSumInsured
      } : {}),
      ...customAddons,
      ...modelData,
      addons
    }
    if (storageData.model_other && that.current.model_data && !that.current.model_data.model_other) {
      delete storageData.model_other
    }
    if (isFleetPolicy) {
      ['transportationType', 'packageType', 'vehicleUse'].forEach((key) => {
        delete storageData[key]
      })
      storageData.package_type = 'offline-protection-car-fleet'
    }
    setToLocalStorage(OFFLINE_FORM_DATA, storageData)
    if (isEditPage) {
      if (urlParams.quoteId !== 'normal') {
        const dataBody = getOfflineStepOneReBody(storageData)
        if (!accessory.current.isModificationChecked) {
          delete dataBody.accessories
          delete dataBody.additional_sum_insured
        }
        delete dataBody.totalSumInsured
        return updateOfflineQuoteReq({
          id: urlParams.quoteId,
          body: dataBody
        })
      }

      return history.push({
        pathname: `/${urlParams.productCode}/${urlParams.purchaseType}/offline/review`,
        state: {
          productCode: urlParams.productCode,
          purchaseType: urlParams.purchaseType
        }
      })
    }
    if (isShowForm) {
      history.push({
        pathname: `/${urlParams.productCode}/${urlParams.purchaseType}/offline/form`,
        state: {
          productCode: urlParams.productCode,
          purchaseType: urlParams.purchaseType
        }
      })
    }
  }, [
    history, isShowForm, urlParams, addons, customAddons,
    isFleetPolicy, isEditPage, validateFormFields, updateOfflineQuoteReq
  ])

  const handleOrderClick = useCallback(() => {
    // const type = otherPolicyType === LANG_STRINGS.fleet ? FLEET_POLICY : MANUAL_ORDER
    history.push({
      pathname: `/${urlParams.productCode}/form/1`,
      state: {
        name: 'Mobil',
        package_type: 'car-protection-comprehensive'
      }
    })
  }, [history, urlParams])

  return (
    <Container
      title={urlParams.purchaseType === MANUAL_ORDER ? LANG_STRINGS.mobilManualOrder : `Mobil: ${LANG_STRINGS.fleet}`}
      hideBottomTabs
      backBtnId='mobilManualOrderStepBack_2'
      loader={
        GET_VEHICLE_YEAR_LOADER || GET_BRAND_LIST_LOADER || GET_VARIANT_LIST_LOADER ||
        GET_REGION_CODE_LOADER || SEND_DOCUMENT_EMAIL_LOADER || UPDATE_OFFLINE_QUOTE_LOADER
      }
    >
      <ManualPolicyStyle>
        {
          !isEditPage && (
            <StepsHeader
              className='application-steps-header'
              leftText={LANG_STRINGS.dataChecking}
              current='1'
              totalSteps='3'
            />
          )
        }
        <ManualPolicyContainerStyle>
          <CustomText
            color={AgentColorPallette.darkCharcoal}
            size='13px'
            weight={700}
          >
            {LANG_STRINGS.completeTheFormToGetInsuranceOption}
          </CustomText>
          {
            isShowForm
              ? (
                <PolicyDataSection
                  isFleetOrder={isFleetPolicy}
                  lossRatio={lossRatio}
                  preFilledData={offlineLocalData.current}
                  resetErrorsKey={resetErrorsKey}
                  getPolicySectionData={handlePolicySectionData}
                  currencyType={currencyType}
                  setCurrencyType={setCurrencyType}
                />
              )
              : (
                <BottomSheetSelect
                  title={LANG_STRINGS.protectionType}
                  onSelect={handleSelectPolicyType}
                  placeholder='Pilih'
                  data={POLICY_TYPE}
                  dataKey='code'
                  displayKey='title'
                  required
                />
              )
          }
        </ManualPolicyContainerStyle>
        <div className='separator' />
        {
          isShowForm && (
            <>
              <PolicyOfflineAddons
                selectedAddons={addons}
                selectedCustomAddons={customAddons || offlineLocalData.current.custom_add_on}
                preFilledAddons={addons || offlineLocalData.current.addons}
                resetErrorsKey={resetErrorsKey}
                preFilledCustomAddons={customAddons.custom_add_on || offlineLocalData.current.custom_add_on}
                currencyType={currencyType}
              />
              {
                !isFleetPolicy && (
                  <>
                    <div className='separator' />
                    <PolicyTransportation
                      title={LANG_STRINGS.transportationType}
                      preFilledData={offlineLocalData.current}
                      resetErrorsKey={resetErrorsKey}
                      getTransportationData={handlePolicySectionData}
                      currencyType={currencyType}
                    />
                    <div className='separator' />
                    <PolicyModification
                      onChangeAccessories={handleAccessories}
                      defaultData={offlineLocalData.current.accessories}
                      resetErrorsKey={resetErrorsKey}
                      totalSumInsured={offlineLocalData.current.totalSumInsured}
                      errorObj={manualFleetFormErrors.accessoryError}
                    />
                  </>
                )
              }
              {
                !isEditPage && (<div className='separator' />)
              }
            </>
          )
        }
        <ManualPolicyContainerStyle padBtm='24%'>
          {
            !isEditPage && (process.env.REACT_APP_SHOW_OFFLINE_FLEET === 'true') && (
              <CustomText
                color={AgentColorPallette.darkCharcoal}
                size='13px'
              >
                {otherPolicyType === LANG_STRINGS.fleet ? LANG_STRINGS.forVehicleMoreThanOneUnitYouCanUse : LANG_STRINGS.forOnlyOneVehicleYouCanUse}&nbsp;
                <span className='golden-text' onClick={handleOrderClick}>
                  {otherPolicyType}.
                </span>
              </CustomText>
            )
          }
        </ManualPolicyContainerStyle>
        {
          policyForm.protection_type && (
            <BottomBtn
              title={btnText}
              icon={SEND_GOLD_ICON}
              iconRight
              onClick={handleToChooseInsurance}
            />
          )
        }
        <ShowSnackbar />
      </ManualPolicyStyle>
    </Container>
  )
}

export default ManualPolicyContainer
