import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useRef } from 'react'
import { CustomText } from '../../../../../components'
import BottomSheetSelect from '../../../../../components/BottomSheetSelect'
import NumericInput from '../../../../../components/NumericInput'
import RadioInputCard from '../../../../../components/RadioInputCard'
import TitleError from '../../../../../components/TitleError'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CAR_PROTECTION } from '../../../../../constants/pkgCode'
import { useGlobalContextValue } from '../../../../../contextProvider/GlobalContext'
import { getIDRCurrency } from '../../../../../helpers/utility'
import { FLEET_SAMPLE_EXCEL_SHEET } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { BENEFIT_TYPE } from '../../constants'
import { usePolicyContextValue } from '../../context'
import { setPolicyState } from '../../state/actions'
import { useGetAllProvider, useGetConversionRate, useSendDocumentToEmail } from '../../state/hooks/usePolicyState'
import PolicyPeriod from '../PolicyPeriod'
import PolicyProviderForm from '../PolicyProviderForm'
import PremiumCalculationNote from '../PremiumCalculationNote'
import { PolicyDataSectionStyle } from './index.style'

function PolicyDataSection ({
  preFilledData, isFleetOrder, lossRatio,
  getPolicySectionData = () => {}, resetErrorsKey = () => {},
  currencyType, setCurrencyType
}) {
  const providerAutoRef = useRef()
  const providerPkgCode = isFleetOrder ? 'offline-offline-protection-car-fleet' : (preFilledData?.package_type ? `offline-${preFilledData?.package_type}` : 'offline-car-protection-comprehensive')
  const [{ getAgentDetailData = {} }] = useGlobalContextValue()
  const [{ packageType, manualFleetFormErrors }, dispatchPolicyState] = usePolicyContextValue()
  const [{ GET_PROVIDER_LIST_LOADER }] = useLoaderContextValue()
  const [{ getProviderListData = [] }, getAllProviderRequest] = useGetAllProvider()
  const [{ getConversionRateData = [] }, getConversionRateDataRequest] = useGetConversionRate()
  const [, sendDocumentEmailRequest] = useSendDocumentToEmail()

  useEffect(() => {
    if (GET_PROVIDER_LIST_LOADER === undefined) {
      getAllProviderRequest({
        query: {
          prov_pg_code: providerPkgCode,
          product_code: CAR_PROTECTION,
          active_online_only: 'false',
          blacklist: 'offline'
        }
      })
    }
  }, [getAllProviderRequest, GET_PROVIDER_LIST_LOADER, providerPkgCode])

  useEffect(() => {
    getConversionRateDataRequest({
      query: {
        exchange_rate_from: 'PPIB'
      }
    })
  }, [getConversionRateDataRequest])

  useEffect(() => {
    getPolicySectionData('currency_label', currencyType?.currency_label)
    getPolicySectionData('exchange_rate', currencyType?.exchange_rate)
    getPolicySectionData('currency_symbol', currencyType?.currency_symbol)
    getPolicySectionData('exchange_rate_from', 'PPIB')
  }, [currencyType, getPolicySectionData])

  const handleBenefitChange = useCallback((data = {}) => {
    dispatchPolicyState(setPolicyState({
      packageType: data.value
    }))
    if (providerAutoRef.current) {
      providerAutoRef.current.resetModalState()
    }
    getAllProviderRequest({
      query: {
        prov_pg_code: `offline-${data.value}`,
        product_code: CAR_PROTECTION,
        active_online_only: 'false',
        blacklist: 'offline'
      }
    })
    getPolicySectionData('providerData', null)
    getPolicySectionData('package_type', data.value)
  }, [dispatchPolicyState, getPolicySectionData, getAllProviderRequest])

  const handleDiscount = useCallback((discount) => {
    getPolicySectionData('discount', discount)
  }, [getPolicySectionData])

  const handleFleetGwp = useCallback((gwp) => {
    if (gwp) {
      resetErrorsKey('total_gwp_ojk_rate')
    }
    getPolicySectionData('total_gwp_ojk_rate', getIDRCurrency(gwp, currencyType?.exchange_rate))
  }, [currencyType?.exchange_rate, getPolicySectionData, resetErrorsKey])

  const handlePolicyPeriod = useCallback((data) => {
    if (data) {
      resetErrorsKey('startDate')
      resetErrorsKey('selectedTimePeriod')
    }
    getPolicySectionData('policyPeriod', data)
  }, [getPolicySectionData, resetErrorsKey])

  const handleExcelUpload = useCallback((data, name) => {
    if (data) {
      resetErrorsKey(name)
    }
    getPolicySectionData(name, data)
  }, [getPolicySectionData, resetErrorsKey])

  const handleLossRatio = useCallback((value) => {
    if (value) {
      resetErrorsKey('loss_ratio')
    }
    getPolicySectionData('loss_ratio', value)
  }, [getPolicySectionData, resetErrorsKey])

  const handleSendEmail = useCallback(() => {
    // handle send email
    sendDocumentEmailRequest({
      body: {
        email: getAgentDetailData.email,
        file_attachment: [{
          name: 'Fleet Sample Excel Sheet',
          url: FLEET_SAMPLE_EXCEL_SHEET
        }]
      }
    })
  }, [sendDocumentEmailRequest, getAgentDetailData])

  const handleSelectCurrencyType = useCallback((data) => {
    if (data) {
      resetErrorsKey('currency_label')
    }
    getPolicySectionData('currency_label', data?.currency_label)
    getPolicySectionData('exchange_rate', data?.exchange_rate)
    getPolicySectionData('currency_symbol', data?.currency_symbol)
    getPolicySectionData('exchange_rate_from', data?.exchange_rate_from)
    setCurrencyType({
      currency_label: data?.currency_label,
      exchange_rate: data?.exchange_rate,
      currency_symbol: data?.currency_symbol
    })
  }, [getPolicySectionData, resetErrorsKey, setCurrencyType])

  return (
    <PolicyDataSectionStyle>
      <CustomText
        color={AgentColorPallette.black}
        weight={800}
        size='16px'
        top='20px'
        bottom='10px'
      >
        {LANG_STRINGS.policyData}
      </CustomText>
      {
        isFleetOrder ? (
          <PremiumCalculationNote
            preFilledUrl={preFilledData.premium_calculation_note}
            excelError={manualFleetFormErrors.premium_calculation_note}
            onSendEmailClick={handleSendEmail}
            onExcelUpload={handleExcelUpload}
          />
        ) : (
          <>
            <RadioInputCard
              data={BENEFIT_TYPE}
              name='benefit_type'
              onChange={handleBenefitChange}
              defaultSelected={preFilledData.package_type || packageType}
              title={LANG_STRINGS.benefitType}
              required
            />
          </>
        )
      }
      <BottomSheetSelect
        title={LANG_STRINGS.currencyType}
        id='currency_type'
        name='currencyType'
        placeholder='Pilih'
        error={manualFleetFormErrors.currency_label ? LANG_STRINGS.required : ''}
        defaultItem={currencyType}
        onSelect={handleSelectCurrencyType}
        data={getConversionRateData.length > 0 ? getConversionRateData : []}
        dataKey='id'
        displayKey='currency_label'
        displayBorder
        required
      />
      <PolicyProviderForm
        resetErrorsKey={resetErrorsKey}
        preFilledData={preFilledData}
        providerAutoRef={providerAutoRef}
        getProviderListData={getProviderListData}
        getPolicySectionData={getPolicySectionData}
        manualFleetFormErrors={manualFleetFormErrors}
      />
      {
        isFleetOrder && (
          <>
            {
              lossRatio && (
                <>
                  <TitleError
                    title={lossRatio.title}
                    error={manualFleetFormErrors.loss_ratio ? LANG_STRINGS.required : ''}
                    required={lossRatio.required}
                  />
                  <NumericInput
                    type='amount'
                    errorField={manualFleetFormErrors.loss_ratio ? 'loss_ratio' : ''}
                    name='loss_ratio'
                    id='loss_ratio'
                    className='number-box-shadow'
                    placeholder='Rp 0'
                    defaultValue={preFilledData.loss_ratio}
                    onChange={handleLossRatio}
                  />
                </>
              )
            }
            <TitleError
              title={LANG_STRINGS.totalGwpBasedOnOjk}
              error={manualFleetFormErrors.total_gwp_ojk_rate ? LANG_STRINGS.required : ''}
              required
            />
            <NumericInput
              type='amount'
              errorField={manualFleetFormErrors.total_gwp_ojk_rate ? 'total_gwp_ojk_rate' : ''}
              name='total_gwp_ojk_rate'
              id='fleetGwp'
              className='number-box-shadow'
              onChange={handleFleetGwp}
              defaultValue={preFilledData.total_gwp_ojk_rate}
              placeholder={`${currencyType?.currency_symbol} 0`}
              amountPrefix={`${currencyType?.currency_symbol} `}
              currencySymbol={currencyType?.currency_symbol}
            />
          </>
        )
      }
      <PolicyPeriod
        onPolicyPeriodSelect={handlePolicyPeriod}
        defaultPeriod={preFilledData?.policyPeriod?.selectedTimePeriod}
        defaultStartDate={preFilledData?.policyPeriod?.startDate}
        defaultEndDate={preFilledData?.policyPeriod?.endDate}
        errorField={manualFleetFormErrors.startDate}
        errorTimePeriod={manualFleetFormErrors.selectedTimePeriod}
      />
      <>
        <TitleError
          title={LANG_STRINGS.discount}
        />
        <NumericInput
          type='discount'
          name='discount'
          id='policyDiscount'
          className='policy-discount number-box-shadow'
          placeholder='0 %'
          maxValue={25}
          onChange={handleDiscount}
          value={preFilledData.discount}
        />
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='11px'
        >
          {LANG_STRINGS.maxDiscountLimit}
        </CustomText>
      </>
    </PolicyDataSectionStyle>
  )
}

export default PolicyDataSection
