import { updateLoader, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useRef, useState, useMemo } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText, InnerInput } from '../../../../../components'
import AutoSearchModal from '../../../../../components/AutoSearchModal'
import NumericInput from '../../../../../components/NumericInput'
import RadioInputCard from '../../../../../components/RadioInputCard'
import TitleError from '../../../../../components/TitleError'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { getConvertedCurrency, getIDRCurrency } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import { getCategory, TRANSPORTATION_TYPE, VEHICLE_USE } from '../../constants'
import { usePolicyContextValue } from '../../context'
import { setPolicyState } from '../../state/actions'
import {
  useGetRegionalCodes, useGetVehicleBrand, useGetVehicleVariant,
  useGetVehicleYear
} from '../../state/hooks/usePolicyState'
import { PolicyTransportationStyle } from './index.style'

function PolicyTransportation ({
  title, preFilledData,
  getTransportationData = () => {}, resetErrorsKey = () => {},
  currencyType
}) {
  const [vehicleAmount, setVehicleAmount] = useState(null)
  const [vehicleInitialAmount, setVehicleInitialAmount] = useState(null)
  const [vehiclePlateNo, setVehiclePlateNo] = useState(preFilledData.vehicle_plate_no || '')
  const [isReset, setIsReset] = useState(false)
  const [
    {
      packageType = '',
      transportationType,
      vehicleUse,
      manualFleetFormErrors
    },
    dispatchPolicyState
  ] = usePolicyContextValue()
  const [{ getRegionCodeData = [] }, getRegionCodesRequest] = useGetRegionalCodes()
  const [{ getVehicleYearData = [] }, getVehicleYearRequest] = useGetVehicleYear()
  const [{ getBrandListData = [] }, getVehicleBrandRequest] = useGetVehicleBrand()
  const [{ getVariantListData = [] }, getVariantRequest] = useGetVehicleVariant()
  const [{ GET_VEHICLE_YEAR_LOADER, GET_REGION_CODE_LOADER }, dispatchLoader] = useLoaderContextValue()
  const vehicleAmountRef = useRef()
  const yearRef = useRef()
  const brandRef = useRef()
  const modelRef = useRef()
  const regionCodeRef = useRef()
  const that = useRef({
    isPreFormDataCall: false,
    packageType: preFilledData.packageType,
    year: preFilledData.year,
    brand: preFilledData.brand,
    model: preFilledData.model
  })
  const resetFields = useMemo(() => {
    return [
      {
        ref: yearRef,
        name: 'year'
      },
      {
        ref: brandRef,
        name: 'brand'
      },
      {
        ref: modelRef,
        name: 'model'
      },
      {
        ref: vehicleAmountRef,
        name: 'amount'
      }
    ]
  }, [])

  useEffect(() => {
    if (GET_VEHICLE_YEAR_LOADER === undefined) {
      getVehicleYearRequest()
    }
    if (GET_REGION_CODE_LOADER === undefined) {
      getRegionCodesRequest()
    }

    if (!that.current.isPreFormDataCall && preFilledData.year) {
      that.current.isPreFormDataCall = true
      const query = {
        category: getCategory(preFilledData.transportationType),
        package_type: preFilledData.packageType
      }
      getVehicleBrandRequest({
        query,
        year: preFilledData.year
      })
      getVariantRequest({
        query,
        params: {
          year: preFilledData.year,
          brand: preFilledData.brand
        }
      })
      setVehicleInitialAmount(preFilledData.vehicle_sum_insured)
    }
  }, [
    getVehicleYearRequest, GET_VEHICLE_YEAR_LOADER,
    getRegionCodesRequest, GET_REGION_CODE_LOADER,
    getVehicleBrandRequest, getVariantRequest,
    preFilledData, currencyType
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_VEHICLE_YEAR_LOADER: undefined,
        GET_REGION_CODE_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const resetVehicleFieldData = useCallback((resetFields = []) => {
    // handle vehicle data
    resetFields.forEach(field => {
      if (field.ref.current) {
        if (field.ref.current.resetModalState) {
          field.ref.current.resetModalState()
        } else {
          setVehicleInitialAmount(null)
          field.ref.current.resetInputValue()
        }
      }
      getTransportationData(field.name, undefined)
      getTransportationData(`${field.name}_data`, undefined)
    })
    setIsReset(true)
  }, [getTransportationData])

  useEffect(() => {
    if (packageType && (that.current.packageType !== packageType)) {
      that.current.packageType = ''
      resetVehicleFieldData(resetFields)
    }
  }, [
    packageType, resetVehicleFieldData, resetFields,
    preFilledData.packageType
  ])

  useEffect(() => {
    if (vehicleInitialAmount && currencyType.exchange_rate) {
      setVehicleAmount(getConvertedCurrency(vehicleInitialAmount, currencyType?.exchange_rate))
    }
  }, [currencyType, vehicleInitialAmount])

  const checkAndResetFields = useCallback((currentType) => {
    const resetArr = []
    if (currentType === 'year') {
      if (that.current.brand) {
        resetArr.push({
          name: 'brand',
          ref: brandRef
        })
      }
      if (that.current.model) {
        resetArr.push({
          name: 'model',
          ref: modelRef
        })
      }
      if (vehicleAmount) {
        resetArr.push({
          name: 'amount',
          ref: vehicleAmountRef
        })
      }
    } else if (currentType === 'brand') {
      if (that.current.model) {
        resetArr.push({
          name: 'model',
          ref: modelRef
        })
        resetArr.push({
          name: 'amount',
          ref: vehicleAmountRef
        })
      }
    }
    resetVehicleFieldData(resetArr)
  }, [vehicleAmount, resetVehicleFieldData])

  const handleSelectAutoInput = useCallback((name, value, data) => {
    const query = {
      category: getCategory(transportationType),
      package_type: packageType
    }
    that.current = {
      ...that.current,
      [name]: value
    }
    if (name === 'year') {
      getVehicleBrandRequest({
        query,
        year: value
      })
      checkAndResetFields('year')
    } else if (name === 'brand') {
      getVariantRequest({
        query,
        params: {
          year: that.current.year,
          brand: that.current.brand
        }
      })
      checkAndResetFields('brand')
    } else if (name === 'model') {
      resetErrorsKey('vehicle_sum_insured')
      setVehicleInitialAmount(data.price)
    }
    resetErrorsKey(name)
    getTransportationData(name, that.current[name])
    getTransportationData(`${name}_data`, data)
  }, [
    getVehicleBrandRequest, getVariantRequest,
    packageType, transportationType, resetErrorsKey,
    checkAndResetFields, getTransportationData
  ])

  const handleRadioChange = useCallback((name, value, data) => {
    // set the selected radio to context level
    if (name === 'transportationType') {
      // clear all vehicle data
      resetVehicleFieldData(resetFields)
    }
    dispatchPolicyState(setPolicyState({
      [name]: value?.value
    }))
    getTransportationData(name, value?.value)
  }, [
    dispatchPolicyState, resetFields,
    getTransportationData, resetVehicleFieldData
  ])

  const handleAmountChange = useCallback((amount) => {
    setVehicleAmount(amount)
    getTransportationData('vehicle_sum_insured', getIDRCurrency(amount, currencyType.exchange_rate))
    resetErrorsKey('vehicle_sum_insured')
  }, [getTransportationData, resetErrorsKey, currencyType])

  const handleVehiclePlateNumber = useCallback((e) => {
    setVehiclePlateNo(e.target.value)
    resetErrorsKey('vehicle_plate_no')
    getTransportationData('vehicle_plate_no', e.target.value)
  }, [getTransportationData, resetErrorsKey])

  const renderRadioCard = useCallback((title, data, name, required, defaultSelected = '') => {
    return (
      <RadioInputCard
        data={data}
        name={name}
        title={title}
        required={required}
        defaultSelected={defaultSelected}
        onChange={(value) => handleRadioChange(name, value, data)}
      />
    )
  }, [handleRadioChange])

  const renderAutoSearchModal = useCallback(({
    name, data, placeholder, id, displayKey, defaultValue,
    dataKey, label, ref, loading, className = '', error = '',
    showCustomAddText = false, showOther = false, isOtherData = false
  }) => {
    return (
      <>
        <TitleError
          title={label}
          error={error ? LANG_STRINGS.required : ''}
          required
        />
        <AutoSearchModal
          errorField={error ? name : ''}
          data={data}
          name={name}
          loading={loading}
          placeholder={placeholder}
          showCustomAddText={showCustomAddText}
          id={`search_modal_${id}`}
          displayKey={displayKey}
          defaultValue={defaultValue}
          className={className}
          dataKey={dataKey}
          title={label}
          ref={ref}
          showOther={showOther}
          isOtherData={isOtherData}
          onSelect={(value, data) => handleSelectAutoInput(name, value, data)}
        />
      </>
    )
  }, [handleSelectAutoInput])

  return (
    <PolicyTransportationStyle>
      <CustomText
        color={AgentColorPallette.black}
        weight={800}
        size='16px'
        bottom='8px'
      >
        {title}
      </CustomText>
      {
        renderRadioCard(
          LANG_STRINGS.transactionType,
          TRANSPORTATION_TYPE,
          'transportationType',
          true,
          (preFilledData.transportationType || transportationType)
        )
      }
      {
        renderRadioCard(
          LANG_STRINGS.vehicleUse,
          VEHICLE_USE,
          'vehicleUse',
          true,
          (preFilledData.vehicleUse || vehicleUse)
        )
      }
      {
        renderAutoSearchModal({
          placeholder: LANG_STRINGS.selectVehicleYear,
          name: 'year',
          data: getVehicleYearData.reverse(),
          label: LANG_STRINGS.productionYear,
          dataKey: 'year',
          displayKey: 'year',
          ref: yearRef,
          defaultValue: isReset ? '' : preFilledData.year,
          error: manualFleetFormErrors.year
        })
      }
      {
        renderAutoSearchModal({
          placeholder: LANG_STRINGS.typeToSearchVehicleBrand,
          name: 'brand',
          data: getBrandListData,
          label: LANG_STRINGS.vehicleBrands,
          dataKey: 'code',
          displayKey: 'name',
          ref: brandRef,
          showCustomAddText: true,
          defaultValue: isReset ? '' : preFilledData.brand,
          isOtherData: preFilledData?.brand_data?.brand_other,
          error: manualFleetFormErrors.brand,
          showOther: true
        })
      }
      {
        renderAutoSearchModal({
          placeholder: LANG_STRINGS.typeToSearchVehicleModel,
          name: 'model',
          data: getVariantListData,
          label: LANG_STRINGS.vehicleModel,
          dataKey: 'model_code',
          displayKey: 'model_name',
          showCustomAddText: true,
          ref: modelRef,
          isOtherData: preFilledData?.model_other,
          defaultValue: isReset ? '' : (preFilledData?.model_other ? preFilledData.model : preFilledData.model_code),
          error: manualFleetFormErrors.model,
          showOther: true
        })
      }
      <>
        <TitleError
          title={LANG_STRINGS.vehiclePrice}
          error={manualFleetFormErrors.vehicle_sum_insured ? LANG_STRINGS.required : ''}
          required
        />
        <NumericInput
          ref={vehicleAmountRef}
          value={vehicleAmount}
          defaultValue={vehicleAmount}
          name='amount'
          type='amount'
          onChange={handleAmountChange}
          id='vehicleAmount'
          className='number-box-shadow'
          wrapperClass='inputWrapepr'
          errorField={manualFleetFormErrors.vehicle_sum_insured ? 'amount' : ''}
          isSkipRegex
          isAllowed={(values) => {
            const { floatValue } = values
            return floatValue > 0
          }}
          placeholder={`${currencyType?.currency_symbol} 0`}
          amountPrefix={`${currencyType?.currency_symbol} `}
          currencySymbol={currencyType?.currency_symbol}
        />

        <Row align='center' justify='space-between'>
          <div className='auto-search-codes'>
            {
              renderAutoSearchModal({
                placeholder: LANG_STRINGS.kode,
                name: 'region_code',
                data: getRegionCodeData,
                label: LANG_STRINGS.kode,
                dataKey: 'region_code',
                displayKey: 'region_code',
                ref: regionCodeRef,
                defaultValue: preFilledData.region_code,
                error: manualFleetFormErrors.region_code
              })
            }
          </div>
          <div className='plate-number-input'>
            <TitleError
              title={LANG_STRINGS.platNumber}
              error={manualFleetFormErrors.vehicle_plate_no ? manualFleetFormErrors.vehicle_plate_no : ''}
              required
            />
            <InnerInput
              errorField={manualFleetFormErrors.vehicle_plate_no ? 'vehicle_plate_no' : ''}
              name='vehicle_plate_no'
              value={vehiclePlateNo}
              placeholder={LANG_STRINGS.platNumberPlaceholder}
              defaultValue={null}
              onChange={handleVehiclePlateNumber}
            />
          </div>
        </Row>
      </>
    </PolicyTransportationStyle>
  )
}

export default PolicyTransportation
